const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=x=>{try{const u=new URL(x);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const paths={check:'m5 12 4 4L19 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',book:'M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3z M4 17h16M8 7h8M8 11h6',plus:'M12 5v14M5 12h14',trash:'M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',search:'M21 21l-6-6 M17 10A7 7 0 1 1 3 10a7 7 0 0 1 14 0',close:'m6 6 12 12M6 18 18 6',alert:'M12 3 2 21h20z M12 9v5M12 18h.01',file:'M6 2h8l5 5v15H6z M14 2v6h5M9 12h7M9 16h7',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',refresh:'M3 11a9 9 0 0 1 15-7l3 3M21 3v5h-5M21 13a9 9 0 0 1-15 7l-3-3M3 21v-5h5',download:'M12 3v12m-5-5 5 5 5-5 M4 17v4h16v-4',external:'M14 3h7v7m0-7-11 11 M11 3H3v18h18v-8',monitor:'M3 3h18v14H3zM8 21h8M12 17v4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 8 0 0 1 16 0v3'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.file}"/></svg>`;
const modeNames={quick:'빠른 점검',release:'배포 전 검수',monitor:'운영 점검'},envNames={demo:'데모',development:'개발',production:'운영'};
const statuses={queued:'검사 대기',running:'검사 중',completed:'검사 완료',failed:'검사 실패',interrupted:'중단됨'};
const workflows={open:'발견',confirmed:'확인 완료',planned:'수정 예정',inprogress:'수정 중',retest:'재검증 대기',resolved:'해결'};
const outcomeNames={pass:'사람 검토 통과',fail:'수정 필요',inapplicable:'비적용 확인','needs-review':'확인 필요','not-tested':'사람 확인 전'},autoNames={clear:['자동 검사 문제 없음','blue'],'not-covered':['자동 검사 대상 아님','']};
const fixes={
 'color-contrast':['텍스트와 배경의 명도 대비가 부족합니다','일반 텍스트는 4.5:1, 큰 텍스트는 3:1 이상으로 조정하세요. 실제 배경·상태와 예외도 확인하세요.'],
 'label':['입력 항목에 접근 가능한 이름이 없습니다','입력 항목에 보이는 레이블을 제공하고 label의 for와 입력 요소의 id를 연결하세요.'],
 'button-name':['버튼의 목적을 알 수 없습니다','버튼 텍스트 또는 적절한 접근 가능한 이름으로 동작의 목적을 설명하세요.'],
 'image-alt':['이미지 대체 텍스트를 확인하세요','정보를 전달하는 이미지에는 동등한 대체 텍스트를 제공하세요. 장식 이미지는 보조기술이 건너뛰도록 처리하세요.'],
 'link-name':['링크의 목적을 알 수 없습니다','문맥에서 목적을 알 수 있는 링크 텍스트나 접근 가능한 이름을 제공하세요.'],
 'html-has-lang':['페이지의 기본 언어가 없습니다','html 요소에 실제 콘텐츠의 기본 언어를 지정하세요. 예: lang="ko".'],
 'document-title':['페이지 제목이 없습니다','페이지의 주제와 목적을 설명하는 고유한 title을 제공하세요.'],
 'aria-required-attr':['구성요소에 필요한 ARIA 속성이 없습니다','해당 역할의 필수 속성을 확인하세요. 네이티브 HTML 요소를 우선 검토하세요.']};
const S={view:'dashboard',runs:[],online:false,loading:true,api:localStorage.getItem('pagecheck-api')||'http://127.0.0.1:47831',token:sessionStorage.getItem('pagecheck-token')||'',selected:null,issue:null,tab:'issues',issueFilter:'violation',env:'all',query:'',sample:false,dialog:null,sessionId:null,returnFocus:null};
const fmt=d=>new Date(d).toLocaleString('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function connectionError(error){return ['TimeoutError','AbortError'].includes(error.name)?'검사 엔진 응답 시간이 초과됐습니다. 실행 창을 확인하고 다시 연결하세요.':error instanceof TypeError?'검사 엔진에 연결할 수 없습니다. 온라인연결.bat 실행, 온라인 주소 허용, 브라우저의 로컬 네트워크 접근 권한을 확인하세요.':error.message}
function setConnection(endpoint,token){const u=new URL(endpoint);if(!['http:','https:'].includes(u.protocol)||!['127.0.0.1','localhost','[::1]'].includes(u.hostname)||u.username||u.password)throw Error('localhost 또는 127.0.0.1 엔진 주소를 입력하세요.');S.api=u.origin;S.token=token.trim();localStorage.setItem('pagecheck-api',S.api);sessionStorage.setItem('pagecheck-token',S.token)}
// 화면이 기대하는 엔진 기능 번호. engine/server.mjs의 ENGINE_BUILD와 같이 올린다.
const ENGINE_BUILD=7,OUTDATED='실행 중인 검사 엔진이 예전 버전이라 이 기능을 쓸 수 없습니다. 검은 실행 창을 닫고 PageCheck열기.bat를 다시 실행하세요.';
async function api(route,options={}){try{const r=await fetch(S.api+route,{signal:AbortSignal.timeout(route==='/api/login'?60000:8000),...options,headers:{'Content-Type':'application/json',Authorization:`Bearer ${S.token}`,...options.headers}});const j=await r.json();if(!r.ok)throw Error(r.status===404&&S.engineOutdated?OUTDATED:j.error||'요청을 처리하지 못했습니다.');return j}catch(error){throw Error(connectionError(error))}}
function connectionFields(){return `<label class="label" for="api-url">엔진 주소</label><input id="api-url" class="field" name="endpoint" value="${esc(S.api)}" required><label class="label" for="api-token">연결 키</label><input id="api-token" class="field" name="token" value="${esc(S.token)}" type="password" autocomplete="off" placeholder="실행 창에 표시된 연결 키"><p class="hint">연결 키는 이 브라우저 세션에만 저장됩니다.</p>`}
function connectionSteps(){return `<ol><li><a href="pagecheck-local.zip" download>로컬 실행 패키지 다운로드</a> 후 압축을 풉니다.</li><li>처음 한 번 <strong>설치.bat</strong>를 실행합니다.</li><li><strong>온라인연결.bat</strong>를 실행하고 이 화면 주소 <strong>${esc(location.href.split('#')[0])}</strong>를 입력합니다.</li><li>실행 창을 열어 둔 채 아래에 연결 키를 입력합니다.</li></ol><p class="hint">연결이 제한되면 <a href="http://127.0.0.1:47831/" target="_blank" rel="noreferrer">이 PC의 검수 화면 열기</a>를 이용하세요.</p>`}
function saveImported(){localStorage.setItem('pagecheck-imports',JSON.stringify(S.runs.filter(r=>r.imported)))}
function shell(){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('check')}</span>PageCheck</div><div class="workspace">REVIEW WORKSPACE</div><nav class="nav" aria-label="주 메뉴">${[['dashboard','grid','검수 현황'],['history','list','검수 기록'],['criteria','shield','검수 기준'],['guide','book','사용 가이드']].map(([id,i,n])=>`<button data-action="nav" data-view="${id}" class="${S.view===id?'active':''}" ${S.view===id?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><p>LOCAL INSPECTION</p><div class="engine-line"><span class="dot ${S.online?'online':''}"></span>${S.online?'검사 엔진 연결됨':'검사 엔진 연결 대기'}</div><button data-action="connect">${S.online?'연결 설정':'엔진 연결하기'}</button><p style="margin-top:15px;color:#849da9;font-size:10px">검수 기록·화면은 PC에 저장됩니다.</p></div></aside><div class="content"><header class="topbar"><div class="breadcrumbs">Workspace <span>/</span><strong>웹 접근성 검수</strong></div><div class="top-actions"><span class="muted">WCAG 2.2 AA</span><button class="btn ghost compact" data-action="connect"><span class="dot ${S.online?'online':''}"></span>${S.online?'엔진 연결됨':'엔진 연결'}</button><div class="avatar" aria-label="내 작업 공간">MY</div></div></header><main id="main" class="main" tabindex="-1">${S.online&&S.engineOutdated?`<div class="banner outdated" role="status"><span><strong>검사 엔진을 다시 시작하세요</strong> · 새 버전 파일로 바꿨지만 실행 중인 엔진은 예전 버전입니다. 검은 실행 창을 닫고 <strong>PageCheck열기.bat</strong>를 다시 실행해야 기록 삭제, 키보드·확대 확인 같은 새 기능이 동작합니다.</span></div>`:''}${S.selected?resultView():S.view==='guide'?guideView():S.view==='criteria'?criteriaView():dashboard()}</main></div></div>${dialogView()}`}
function render(){const active=$(':focus');const aid=active?.id;$('#app').innerHTML=shell();if(S.dialog){setTimeout(()=>document.querySelector('.modal input:not([type=hidden]),.modal select,.modal textarea,.modal button')?.focus(),0)}if(aid&&!S.dialog)$('#'+aid)?.focus();loadEvidence();loadShots()}
function stat(label,num,note,i,tone=''){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><div class="stat-num ${tone}">${esc(num)}</div><div class="stat-note">${note}</div></div>`}
function dashboard(){
 const list=S.runs.filter(r=>S.env==='all'||r.request.environment===S.env).filter(r=>!S.query||JSON.stringify([r.request.name,r.request.urls]).toLowerCase().includes(S.query.toLowerCase()));
 const open=S.runs.reduce((a,r)=>a+(r.summary?.open||0),0),review=S.runs.reduce((a,r)=>a+(r.summary?.review||0),0),active=S.runs.filter(r=>['running','queued'].includes(r.status)).length;
 return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:7px">${S.view==='history'?'REVIEW HISTORY':'QUALITY BEFORE RELEASE'}</div><h1>${S.view==='history'?'검수 기록':'배포 전, 한 번 더 확인하세요.'}</h1><p class="muted">데모부터 운영까지, 접근성 문제를 발견하고 수정 후 다시 확인하세요.</p></div><button class="btn primary" data-action="new">${icon('plus')}새 검수</button></div>
 ${S.view==='history'?'':`<section class="hero"><div><div class="eyebrow">CHECK. FIX. CHECK AGAIN.</div><h2>문제를 찾는 데서 끝나지 않는 검수</h2><p>발생 위치와 수정 방법을 확인하고, 같은 조건으로 재검수하세요.<br>자동 검사와 사람이 확인할 항목을 함께 관리합니다.</p></div><div class="hero-art" aria-hidden="true">${[['monitor','페이지 등록'],['search','접근성 검사'],['refresh','수정·재검수']].map(([i,n],ix)=>`${ix?'<span class="flow-arrow">→</span>':''}<div class="flow-node">${icon(i)}${n}</div>`).join('')}</div></section>`}
 <div class="stats">${stat('전체 검수',S.runs.length,'이 PC 또는 가져온 검수 기록','file')}${stat('수정 필요한 문제',open,'검수 기록별 미해결 문제 합계','alert','red')}${stat('사람 확인 필요',review,'도구만으로 확정하지 않은 항목','user','amber')}${stat('진행 중인 검수',active,'대기 중인 검사 포함','clock')}</div>
 <section><div class="section-head"><h2>${S.view==='history'?'전체 검수 기록':'최근 검수'}<span class="count">${S.runs.length}</span></h2><div style="display:flex;gap:8px"><button class="btn ghost compact" data-action="import">${icon('download')}결과 가져오기</button><button class="btn ghost compact" data-action="refresh">${icon('refresh')}새로고침</button></div></div><div class="toolbar"><div class="segments" aria-label="검수 환경 필터">${[['all','전체'],['development','개발'],['demo','데모'],['production','운영']].map(([v,n])=>`<button class="${S.env===v?'active':''}" data-action="env" data-env="${v}" aria-pressed="${S.env===v}">${n}</button>`).join('')}</div><label class="search">${icon('search')}<input id="run-search" aria-label="검수 이름 또는 URL 검색" placeholder="이름 또는 URL 검색" value="${esc(S.query)}"></label></div>
 <div class="table-wrap"><table class="table"><thead><tr><th scope="col">검수 페이지</th><th scope="col">환경 / 모드</th><th scope="col">결과</th><th scope="col">상태</th><th scope="col">검수 일시</th><th scope="col"><span class="small">상세</span></th></tr></thead><tbody>${list.map(r=>`<tr class="table-row"><td><div class="run-name"><button class="btn ghost" style="padding:0;font-size:13px;text-align:left;white-space:normal" data-action="open" data-id="${r.id}">${esc(r.request.name)}</button>${r.imported?' <span class="pill">가져옴</span>':''}</div><div class="url">${esc(r.request.urls[0])}</div></td><td><span class="pill ${r.request.environment==='production'?'green':r.request.environment==='demo'?'amber':'blue'}">${envNames[r.request.environment]}</span><div class="small muted" style="margin-top:5px">${modeNames[r.request.mode]}</div></td><td><span style="color:var(--red)">수정 ${r.summary?.open||0}</span> <span class="muted">· 확인 ${r.summary?.review||0}</span></td><td><span class="pill ${r.status==='completed'?'green':r.status==='failed'?'red':'amber'}">${statuses[r.status]}</span>${r.request.baselineId?'<div class="small muted">재검수</div>':''}</td><td class="muted">${fmt(r.createdAt)}</td><td><div class="row-actions"><button class="btn ghost compact" aria-label="${esc(r.request.name)} 상세 보기" data-action="open" data-id="${r.id}">${icon('arrow')}</button><button class="btn ghost compact danger" aria-label="${esc(r.request.name)} 기록 삭제" data-action="delete" data-id="${r.id}" ${r.status==='running'?'disabled':''}>${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table>${!list.length?`<div class="empty"><div class="empty-icon">${icon('monitor')}</div><h3>${S.loading?'검수 기록을 불러오고 있습니다':'첫 번째 검수를 시작해 보세요'}</h3><p class="muted">개발 중인 페이지의 주소만 있으면 시작할 수 있습니다.<br>검사 엔진을 연결하거나 예시 결과를 먼저 둘러보세요.</p><button class="btn primary" data-action="new">${icon('plus')}페이지 검수하기</button></div>`:''}</div></section>
 <div class="bottom-grid"><section class="panel"><h3>이렇게 검수하세요</h3><div class="steps-list">${[['01','페이지 등록','환경·변경 내용과 범위 설정'],['02','결과 확인','문제 위치와 관련 기준 확인'],['03','수정 처리','담당자·진행 상태 관리'],['04','재검수','해결·유지·신규 문제 비교']].map(([n,t,d])=>`<div class="step-mini"><div class="step-no">${n}</div><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></section><section class="panel sample-card"><div class="eyebrow" style="color:#8a753f;margin-bottom:8px">START WITH AN EXAMPLE</div><h3 style="margin-bottom:7px">검수 결과가 궁금하다면</h3><p>의도적으로 문제가 있는 예시 페이지의 검사 결과를 확인해 보세요. 실제 프로젝트 기록과 구분됩니다.</p><button class="btn compact" data-action="sample">예시 결과 둘러보기 ${icon('arrow')}</button></section></div>`;
}
function selected(){return S.sample?S.demo:S.runs.find(r=>r.id===S.selected)}
function resultView(){
 const r=selected();if(!r){S.selected=null;return dashboard()};const sum=r.summary||{};const busy=['running','queued'].includes(r.status);
 return `<button class="back" data-action="back">${icon('back')}검수 목록으로</button>${S.sample?'<div class="banner"><span><strong>예시 데이터</strong> · 예시 페이지에서 생성한 결과이며, 회사 페이지를 검사한 기록이 아닙니다.</span><button class="btn ghost compact" data-action="new">내 페이지 검수</button></div>':''}
 <div class="page-heading result-heading"><div><h1>${esc(r.request.name)}</h1><div class="result-sub"><span class="pill blue">${envNames[r.request.environment]}</span><span class="pill">${modeNames[r.request.mode]}</span><span class="url">${esc(r.request.urls[0])}</span><span class="small muted">${fmt(r.createdAt)}</span></div></div><div class="result-controls"><button class="btn danger" data-action="delete" data-id="${r.id}" ${r.status==='running'||S.sample?'disabled':''}>${icon('trash')}기록 삭제</button><button class="btn" data-action="export">${icon('download')}결과 내보내기</button><button class="btn primary" data-action="recheck" ${busy||S.sample||r.imported?'disabled':''}>${icon('refresh')}같은 조건으로 재검수</button></div></div>
 <div class="summary-band">${icon(busy?'clock':'shield')}<div><strong>${esc(sum.decision||statuses[r.status])}</strong><p>${busy?'브라우저가 페이지와 상태를 검사하고 있습니다.':'자동 검사 결과입니다. 미검사 기준과 사람 확인 항목까지 검토한 뒤 배포 여부를 결정하세요.'}</p>${busy?'<div class="mini-bar"><span></span></div>':''}</div><span class="small">전체 기준 ${sum.assessed||0} / 55 평가</span></div>
 ${r.comparison?`<div class="banner" style="background:#edf6f0;border-color:#d5e7da;color:#326149"><span><strong>이전 검수와 비교</strong> · 해결 ${r.comparison.resolved.length} · 유지 ${r.comparison.remaining.length} · 신규 ${r.comparison.new.length} · 비교 불가 ${r.comparison.unverified.length}</span></div>`:''}
 <div class="stats">${stat('수정 필요',sum.open||0,'자동 규칙의 미해결 문제','alert','red')}${stat('사람 확인 필요',sum.review||0,'검토 후 판정할 항목','user','amber')}${stat('사람 확인 전 기준',sum.untested??55,sum.autoNone==null?'55개 A·AA 기준 중 사람 판정 전':`자동 검사 문제 없음 ${Number(sum.autoClear)}개<br>자동 검사 대상 아님 ${Number(sum.autoNone)}개`,'shield')}${stat('검사한 화면·상태',sum.states||0,`검사하지 못한 상태 ${sum.errors||0}개`,'monitor')}</div>
 <div class="tabs" role="tablist" aria-label="검수 결과"><button id="tab-issues" aria-controls="result-panel" role="tab" tabindex="${S.tab==='issues'?0:-1}" aria-selected="${S.tab==='issues'}" data-action="tab" data-tab="issues" class="${S.tab==='issues'?'active':''}">문제 목록</button><button id="tab-coverage" aria-controls="result-panel" role="tab" tabindex="${S.tab==='coverage'?0:-1}" aria-selected="${S.tab==='coverage'}" data-action="tab" data-tab="coverage" class="${S.tab==='coverage'?'active':''}">기준별 평가</button><button id="tab-scope" aria-controls="result-panel" role="tab" tabindex="${S.tab==='scope'?0:-1}" aria-selected="${S.tab==='scope'}" data-action="tab" data-tab="scope" class="${S.tab==='scope'?'active':''}">자동 규칙·검사 기록</button></div>
 <div role="tabpanel" id="result-panel" aria-labelledby="tab-${S.tab}">${S.tab==='issues'?issuesView(r):S.tab==='coverage'?coverageView(r):scopeView(r)}</div>`;
}
function issueTitle(i){return fixes[i.ruleId]?.[0]||i.title}
function issuesView(r){
 const issues=r.issues.filter(i=>S.issueFilter==='all'||(S.issueFilter==='error'?false:i.type===S.issueFilter));const chosen=r.issues.find(i=>i.id===S.issue)||issues[0];if(chosen&&!S.issue)S.issue=chosen.id;
 return `<div class="toolbar"><div class="segments">${[['violation','수정 필요'],['review','사람 확인'],['error','검사 못함'],['all','전체']].map(([v,n])=>`<button class="${S.issueFilter===v?'active':''}" data-action="issue-filter" data-filter="${v}">${n}</button>`).join('')}</div><span class="small muted">발생 위치별로 표시됩니다.</span></div><div class="result-layout"><div class="issue-list">${S.issueFilter==='error'?r.states.filter(s=>s.status==='error').map(s=>`<div class="panel"><span class="pill amber">미검사</span><h3 style="margin:10px 0">${esc(s.label)}</h3><p class="small muted">${esc(s.url)}</p><p class="error">${esc(s.error)}</p></div>`).join(''):issues.map(i=>`<button class="issue-card ${chosen?.id===i.id?'selected':''}" data-action="issue" data-id="${i.id}" aria-pressed="${chosen?.id===i.id}"><div class="issue-top"><span class="pill ${i.workflow==='resolved'?'green':i.type==='review'?'amber':'red'}">${i.workflow==='resolved'?'해결':i.type==='review'?'사람 확인':i.impact==='critical'?'높은 영향':i.impact==='serious'?'주요 문제':'수정 필요'}</span>${i.scIds.map(c=>`<span class="pill">${c}</span>`).join('')}<span class="small muted" style="margin-left:auto">${workflows[i.workflow]}</span></div><h3>${esc(issueTitle(i))}</h3><code>${esc(i.selector)}</code><div class="issue-footer"><span>${i.viewport==='mobile'?'모바일':'PC'} · ${esc(i.stateLabel||'초기 화면')}</span><span>${esc(i.owner||'담당자 미지정')}</span></div></button>`).join('')}${(!issues.length&&S.issueFilter!=='error')||S.issueFilter==='error'&&!r.states.some(s=>s.status==='error')?'<div class="panel empty"><div class="empty-icon">'+icon('check')+'</div><h3>이 목록에 해당하는 항목이 없습니다</h3><p class="muted">기준별 평가와 검사 범위를 함께 확인하세요.</p></div>':''}</div>${S.issueFilter!=='error'&&chosen?detailView(chosen,r):'<aside class="panel"><h3>검수 결과 읽는 방법</h3><p class="explanation">자동 검사에서 발견되지 않았더라도 전체 기준의 통과를 의미하지 않습니다. 실제 화면·상태와 미검사 범위를 함께 확인하세요.</p></aside>'}</div>`;
}
function detailView(i,r){return `<aside class="panel detail"><div class="detail-head"><h3>문제 상세</h3><span class="pill">${esc(i.ruleId)}</span></div><strong style="font-size:14px">${esc(issueTitle(i))}</strong><div class="screenshot-box" id="evidence-box" data-evidence="${esc(i.screenshot||'')}"><div class="image-label">${S.sample?'예시 페이지 화면':'검사 당시 화면'} · ${i.viewport==='mobile'?'390 × 844':'1440 × 1000'}</div><div id="evidence-image" class="small muted" style="min-height:120px;padding:12px">${i.screenshot?'화면을 불러오는 중입니다.':'저장된 화면이 없습니다.'}</div></div><h3>무엇이 문제인가요</h3>${checkList(i)}<h3>확인·수정 방법</h3><p class="explanation">${esc(fixes[i.ruleId]?.[1]||i.description)}</p><details><summary class="small">도구의 관찰 원문과 HTML</summary><p class="explanation">${esc(i.explanation)}</p><code class="small" style="word-break:break-all">${esc(i.html)}</code></details><h3 style="margin-top:19px">재현 순서</h3><ol>${i.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><a class="small" href="${esc(safeLink(i.helpUrl))}" target="_blank" rel="noreferrer">검사 규칙과 근거 확인 ↗</a>
 <form id="issue-form"><input type="hidden" name="issueId" value="${i.id}"><label>진행 상태<select class="field" name="workflow">${Object.entries(workflows).filter(([v])=>v!=='resolved'||i.type==='review'||i.source==='manual'||i.workflow==='resolved').map(([v,n])=>`<option value="${v}" ${v===i.workflow?'selected':''}>${n}</option>`).join('')}</select></label><label>담당자<input class="field" name="owner" value="${esc(i.owner)}" placeholder="예: 프론트엔드 담당자"></label><label>수정·검토 메모<textarea class="field" name="note" placeholder="수정 내용 또는 판정 근거를 남기세요.">${esc(i.note)}</textarea></label><div class="detail-actions"><button type="submit" class="btn compact" ${S.sample||r.imported?'disabled':''}>변경 저장</button><button type="button" class="btn primary compact" data-action="recheck" ${S.sample||r.imported||['queued','running'].includes(r.status)?'disabled':''}>재검수</button></div><p class="hint">자동 위반의 해결 여부는 같은 조건의 재검수로 확인합니다.</p></form></aside>`}
// HTML 보고서: 문제 위치를 잘라 낸 화면을 넣은 파일 하나. PageCheck 없이 브라우저로 열어 볼 수 있다.
const runById=id=>S.sample&&S.demo?.id===id?S.demo:S.runs.find(x=>x.id===id);
async function reportImage(r,shot,kind){
 if(!shot||r.imported)return null;let src;
 if(S.sample)src=kind?`sample-${kind}.png`:'sample-evidence.png';
 else{src=shotCache.get(shot);if(!src){const response=await fetch(S.api+'/api/evidence/'+shot,{headers:{Authorization:`Bearer ${S.token}`}});if(!response.ok)return null;src=URL.createObjectURL(await response.blob());shotCache.set(shot,src)}}
 const img=new Image();img.src=src;try{await img.decode()}catch{return null}return img;
}
// 문제 요소 주변을 잘라 빨간 상자를 그린다. 위치를 모르면 화면 위쪽을 넣는다.
function reportCrop(img,b){
 const W=img.naturalWidth,H=img.naturalHeight,located=!!(b&&b.width&&b.height&&b.x<W&&b.y<H&&b.x+b.width>0&&b.y+b.height>0);
 let cx=0,cy=0,cw=W,ch=Math.min(H,900);
 if(located){cw=Math.min(W,Math.max(480,b.width+320));ch=Math.min(H,Math.max(240,b.height+200));cx=Math.max(0,Math.min(W-cw,b.x+b.width/2-cw/2));cy=Math.max(0,Math.min(H-ch,b.y+b.height/2-ch/2))}
 const k=Math.min(1,720/cw),c=document.createElement('canvas');c.width=Math.round(cw*k);c.height=Math.round(ch*k);
 const g=c.getContext('2d');g.drawImage(img,cx,cy,cw,ch,0,0,c.width,c.height);
 if(located){g.strokeStyle='#d32f2f';g.lineWidth=3;g.strokeRect((b.x-cx)*k-2,(b.y-cy)*k-2,b.width*k+4,b.height*k+4)}
 return {url:c.toDataURL('image/jpeg',.82),located};
}
function reportWhole(img,maxH=2400){const k=Math.min(1,900/img.naturalWidth),h=Math.min(img.naturalHeight,maxH),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*k);c.height=Math.round(h*k);c.getContext('2d').drawImage(img,0,0,img.naturalWidth,h,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.8)}
const REPORT_CSS=`:root{color-scheme:light}body{margin:0;background:#f6f8f9;color:#182b3b;font:14px/1.6 "Malgun Gothic",Arial,sans-serif}main{max-width:960px;margin:0 auto;padding:32px 20px 60px}h1{font-size:26px;margin:0 0 6px}h2{font-size:19px;margin:40px 0 12px;padding-top:12px;border-top:2px solid #e3e8eb}h3{font-size:15px;margin:0 0 6px}.muted{color:#5b6b7a}.small{font-size:12px}.notice{background:#fff8e6;border:1px solid #e9d9ae;color:#5e4712;border-radius:8px;padding:12px 16px;margin:16px 0}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:16px 0}.stat{background:#fff;border:1px solid #e3e8eb;border-radius:8px;padding:12px 14px}.stat b{display:block;font-size:24px}.red{color:#a93536}.amber{color:#7a560f}.green{color:#1e674f}.issue{background:#fff;border:1px solid #e3e8eb;border-radius:10px;padding:18px;margin:14px 0;break-inside:avoid}.tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}.tag{border:1px solid #d5dde2;border-radius:99px;padding:1px 9px;font-size:12px}.tag.red{border-color:#e6c9c9;background:#fbeeee}.tag.amber{border-color:#e9d9ae;background:#fff8e6}figure{margin:12px 0}figure img{display:block;max-width:100%;height:auto;border:1px solid #d5dde2;border-radius:6px}figcaption{font-size:12px;color:#5b6b7a;margin-top:4px}dl{display:grid;grid-template-columns:110px 1fr;gap:4px 12px;margin:10px 0;font-size:13px}dt{color:#5b6b7a}dd{margin:0;word-break:break-all}code,pre{font:12px/1.5 Consolas,monospace;background:#f1f4f6;border-radius:4px}code{padding:1px 4px}pre{padding:10px;white-space:pre-wrap;word-break:break-all;margin:6px 0}.checklist{list-style:none;padding:0;margin:8px 0}.checklist li{display:flex;gap:8px;margin:4px 0}.checklist li div{display:flex;flex-direction:column}.mark{font-weight:700;width:14px;flex:none}.mark.bad{color:#a93536}.mark.warn{color:#7a560f}.swatch{display:inline-block;width:12px;height:12px;border:1px solid #888;border-radius:2px;vertical-align:-1px;margin:0 4px}table{width:100%;border-collapse:collapse;background:#fff;font-size:13px}th,td{border:1px solid #e3e8eb;padding:7px 9px;text-align:left;vertical-align:top}th{background:#f1f4f6}a{color:#15608f}ol{padding-left:20px;margin:6px 0}li{margin:4px 0}@media print{body{background:#fff}.issue{border-color:#bbb}}`;
function reportIssue(i,n,shot,r){
 const tone=i.type==='violation'?'red':'amber';
 return `<article class="issue" id="issue-${n}"><div class="tags"><span class="tag ${tone}">${i.type==='violation'?(i.impact==='critical'?'높은 영향':i.impact==='serious'?'주요 문제':'수정 필요'):'사람 확인'}</span>${i.scIds.map(c=>`<span class="tag">WCAG ${esc(c)}</span>`).join('')}<span class="tag">${esc(workflows[i.workflow]||i.workflow)}</span>${r.comparison?.new?.includes(i.fingerprint)?'<span class="tag">이번에 새로 발견</span>':''}</div>
 <h3>${n}. ${esc(issueTitle(i))}</h3>
 ${shot?`<figure><img src="${shot.url}" alt="${esc(issueTitle(i))} 위치를 표시한 검사 화면"><figcaption>${shot.located?'빨간 상자가 문제 요소입니다.':'위치 정보가 없어 화면 위쪽을 넣었습니다. 아래 선택자로 요소를 찾으세요.'}</figcaption></figure>`:`<p class="small muted">${r.imported?'가져온 결과라 화면이 없습니다.':'저장된 화면이 없습니다.'}</p>`}
 <dl><dt>페이지</dt><dd>${esc(i.url)}</dd><dt>화면·상태</dt><dd>${i.viewport==='mobile'?'모바일':'PC'} · ${esc(i.stateLabel||'초기 화면')}</dd><dt>요소 위치</dt><dd><code>${esc(i.selector)}</code></dd>${i.owner?`<dt>담당자</dt><dd>${esc(i.owner)}</dd>`:''}${i.note?`<dt>메모</dt><dd>${esc(i.note)}</dd>`:''}<dt>규칙</dt><dd>${esc(i.ruleId)}</dd></dl>
 <h3>무엇이 문제인가요</h3>${checkList(i)}
 <h3>확인·수정 방법</h3><p>${esc(fixes[i.ruleId]?.[1]||i.description)}</p>
 ${i.html?`<h3>요소 HTML</h3><pre>${esc(i.html)}</pre>`:''}
 <h3>재현 순서</h3><ol>${i.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>
 ${i.helpUrl?`<p class="small"><a href="${esc(safeLink(i.helpUrl))}">검사 규칙과 근거 ↗</a></p>`:''}</article>`;
}
async function buildReport(r,progress){
 const active=r.issues.filter(i=>i.workflow!=='resolved'),order=[...active.filter(i=>i.type==='violation'),...active.filter(i=>i.type!=='violation')],resolved=r.issues.filter(i=>i.workflow==='resolved');
 const imgs=new Map(),image=async(shot,kind)=>{if(!imgs.has(shot))imgs.set(shot,await reportImage(r,shot,kind).catch(()=>null));return imgs.get(shot)};
 const blocks=[];for(const [ix,i] of order.entries()){progress(ix+1,order.length);const img=await image(i.screenshot,i.checkKind);blocks.push(reportIssue(i,ix+1,img?reportCrop(img,i.bounds):null,r))}
 const checks=[];for(const k of (r.checks||[])){const img=k.kind==='keyboard'&&k.status==='completed'?await image(k.screenshot,k.kind):null;checks.push(`<h3>${esc(k.label)}${new Set((r.checks||[]).map(x=>x.url)).size>1?` <span class="small muted">${esc(k.url)}</span>`:''}</h3>${k.status==='completed'?`<ul>${Object.entries(k.notes).map(([sc,t])=>`<li>${esc(sc)} · ${esc(t)}</li>`).join('')}</ul>`:`<p class="red">확인하지 못함: ${esc(k.error||'')}</p>`}${img?`<figure><img src="${reportWhole(img)}" alt="Tab 키 포커스 순서를 번호로 표시한 화면"><figcaption>파란 번호는 Tab 이동 순서, 빨간 상자는 포커스 표시나 위치를 확인해야 하는 요소입니다.</figcaption></figure>`:''}`)}
 const s=r.summary||{},cov=r.coverage||[],count=k=>cov.filter(c=>c.outcome===k).length,title=`${r.request.name} — 접근성 검수 보고서`;
 return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'"><title>${esc(title)}</title><style>${REPORT_CSS}</style></head><body><main>
 <p class="small muted">PageCheck 접근성 검수 보고서</p><h1>${esc(r.request.name)}</h1>
 <p class="muted">${envNames[r.request.environment]||''} · ${modeNames[r.request.mode]||''} · 검사 ${esc(new Date(r.createdAt).toLocaleString('ko-KR'))} · 보고서 ${esc(new Date().toLocaleString('ko-KR'))}</p>
 <ul>${r.request.urls.map(u=>`<li style="word-break:break-all">${esc(u)}</li>`).join('')}</ul>
 ${r.request.changeNote?`<p>변경 내용: ${esc(r.request.changeNote)}</p>`:''}
 <div class="notice"><strong>${esc(s.decision||statuses[r.status]||'')}</strong><br>자동 검사로 모든 접근성 문제를 찾을 수는 없습니다. ‘사람 확인’ 항목과 기준별 평가가 끝나야 검수가 끝납니다. 이 파일에는 검사한 페이지 화면이 들어 있으니 회사 안에서만 공유하세요.${S.sample?'<br>예시 데이터로 만든 보고서입니다.':''}</div>
 <div class="stats"><div class="stat">수정 필요<b class="red">${s.open||0}</b></div><div class="stat">사람 확인 필요<b class="amber">${s.review||0}</b></div><div class="stat">기준 평가 완료<b>${s.assessed||0} / 55</b></div><div class="stat">검사하지 못한 화면<b>${s.errors||0}</b></div></div>
 <h2>목차</h2><ol><li><a href="#issues">문제 목록 (${order.length})</a></li><li><a href="#criteria">기준별 평가</a></li>${checks.length?'<li><a href="#checks">키보드·확대 자동 확인</a></li>':''}<li><a href="#scope">검사 범위와 기록</a></li></ol>
 <h2 id="issues">문제 목록</h2>${order.length?`<p class="muted small">수정 필요 ${order.filter(i=>i.type==='violation').length}개, 사람 확인 ${order.filter(i=>i.type!=='violation').length}개입니다. 같은 문제가 여러 요소에서 나오면 요소마다 따로 적었습니다.</p>${blocks.join('')}`:'<p>해결되지 않은 문제가 없습니다.</p>'}
 ${resolved.length?`<h3>해결된 문제 ${resolved.length}개</h3><ul>${resolved.map(i=>`<li>${esc(issueTitle(i))} · <code>${esc(i.selector)}</code></li>`).join('')}</ul>`:''}
 <h2 id="criteria">기준별 평가 (WCAG 2.2 A·AA 55개)</h2><p class="small muted">수정 필요 ${count('fail')} · 확인 필요 ${count('needs-review')} · 사람 검토 통과 ${count('pass')} · 비적용 확인 ${count('inapplicable')} · 사람 확인 전 ${count('not-tested')}</p>
 <table><thead><tr><th scope="col">기준</th><th scope="col">판정</th><th scope="col">근거·자동 확인 결과</th></tr></thead><tbody>${cov.map(c=>`<tr><th scope="row">${esc(c.id)} ${esc(c.title)} <span class="small muted">(${esc(c.level)})</span></th><td class="${c.outcome==='fail'?'red':c.outcome==='needs-review'?'amber':c.outcome==='pass'||c.outcome==='inapplicable'?'green':''}">${esc(outcomeNames[c.outcome]||c.outcome)}</td><td>${c.review?`${esc(c.review.note)}<br><span class="small muted">검토자 ${esc(c.review.reviewer)} · ${esc(fmt(c.review.at))}</span>`:''}${(c.evidence||[]).map(e=>`<div class="small">${esc(e.label)}: ${esc(e.text)}</div>`).join('')}${c.suggest?`<div class="small muted">해당 없음 제안: ${esc(c.suggest.reason)}</div>`:''}</td></tr>`).join('')}</tbody></table>
 ${checks.length?`<h2 id="checks">키보드·확대 자동 확인</h2><p class="small muted">실제로 Tab 키를 누르고 화면 너비·글자 간격을 바꿔 확인한 결과입니다. 찾은 후보는 문제 목록의 ‘사람 확인’에 있습니다.</p>${checks.join('')}`:''}
 <h2 id="scope">검사 범위와 기록</h2><p>${esc(r.engine?.name||'')} ${esc(r.engine?.version||'')} · ${esc(r.engine?.standard||'')} · ${esc(r.engine?.browser||'')}</p>
 <table><thead><tr><th scope="col">화면·상태</th><th scope="col">결과</th></tr></thead><tbody>${r.states.map(st=>`<tr><th scope="row">${esc(st.label)} · ${st.viewport==='mobile'?'모바일':'PC'}<br><span class="small muted">${esc(st.url)}</span></th><td>${st.status==='completed'?`검사 완료 · 발견 ${st.findings||0}건`:`<span class="red">검사 못함: ${esc(st.error||'')}</span>`}</td></tr>`).join('')}</tbody></table>
 <p class="small muted">PageCheck가 만든 보고서입니다. 수정한 뒤에는 PageCheck에서 같은 조건으로 재검수하세요.</p></main></body></html>`;
}
async function exportReport(id,button){const r=runById(id);button.disabled=true;const label=button.innerHTML;
 try{const html=await buildReport(r,(n,t)=>{button.textContent=`화면 넣는 중 ${n}/${t}`});
  download(new Blob([html],{type:'text/html;charset=utf-8'}),`${fileSafe(r.request.name)}-접근성보고서-${new Date(r.createdAt).toISOString().slice(0,10)}.html`);
  toast(`HTML 보고서를 저장했습니다 (약 ${Math.max(.1,new Blob([html]).size/1048576).toFixed(1)}MB).`)}
 catch(e){toast('보고서를 만들지 못했습니다: '+e.message)}finally{if(button.isConnected){button.disabled=false;button.innerHTML=label}}}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const fileSafe=s=>String(s||'pagecheck').replace(/[\\/:*?"<>|\s]+/g,'_').slice(0,60);
let lastBlob;
const pct=(a,b)=>`${(a/b*100).toFixed(3)}%`;
function markerHtml(b,x,y,w,h){return `<span class="marker" style="left:${pct(b.x-x,w)};top:${pct(b.y-y,h)};width:${pct(b.width,w)};height:${pct(b.height,h)}"></span>`}
// 문제 요소 주변 확대 화면과, 펼쳐 보는 전체 화면. W·H는 저장된 화면 이미지의 실제 크기.
// 키보드·확대 자동 확인의 증거 화면. 한 번 받은 화면은 다시 받지 않는다.
const shotCache=new Map();
async function loadShots(root=document){const r=selected();if(!r)return;
 for(const box of root.querySelectorAll('[data-shot]:not([data-loaded])')){if(box.closest('details:not([open])'))continue;box.dataset.loaded='1';
  try{let src;if(S.sample)src=`sample-${box.dataset.kind}.png`;else if(r.imported){box.textContent='가져온 결과의 화면 파일은 원래 검사 PC에서 확인하세요.';continue}
   else{src=shotCache.get(box.dataset.shot);if(!src){const response=await fetch(S.api+'/api/evidence/'+box.dataset.shot,{headers:{Authorization:`Bearer ${S.token}`}});if(!response.ok)throw Error();src=URL.createObjectURL(await response.blob());shotCache.set(box.dataset.shot,src)}}
   box.innerHTML=`<img src="${esc(src)}" alt="${esc(box.dataset.alt||'자동 확인 증거 화면')}">`}
  catch{box.textContent='화면 파일을 불러올 수 없습니다. 엔진 연결을 확인하세요.'}}}
document.addEventListener('toggle',e=>{if(e.target.matches?.('details[open]'))loadShots(e.target)},true);
function shotBox(k){return `<div class="shot" data-shot="${esc(k.screenshot)}" data-kind="${esc(k.kind)}" data-alt="${esc(k.label)} 증거 화면">화면 불러오는 중…</div>`}
function evidenceLines(c){return (c.evidence||[]).map(e=>`<p class="evidence-line"><strong>${esc(e.label)}</strong> ${esc(e.text)}</p>`).join('')}
function evidenceHtml(i,src,W,H){
 const b=i.bounds,alt=`${i.stateLabel||'초기 화면'} 검사 당시 화면`;
 const whole=()=>`<div class="whole-wrap"><div style="position:relative"><img src="${esc(src)}" alt="${esc(alt)}">${b&&b.width&&b.height?markerHtml(b,0,0,W,H):''}</div></div>`;
 if(!b)return `${whole()}<p class="evidence-note">위치 정보가 없습니다. ‘도구의 관찰 원문과 HTML’의 선택자로 요소를 찾으세요.</p>`;
 if(!b.width||!b.height)return `${whole()}<p class="evidence-note">화면에 크기가 없는(숨겨진) 요소라 위치를 표시할 수 없습니다. 선택자로 요소를 찾으세요.</p>`;
 if(b.x>=W||b.y>=H||b.x+b.width<=0||b.y+b.height<=0)return `${whole()}<p class="evidence-note">문제 요소가 저장된 화면 범위 밖(첫 화면 아래)에 있습니다. 같은 조건으로 재검수하면 페이지 전체 화면에 위치를 표시합니다.</p>`;
 const cw=Math.min(W,Math.max(320,b.width+240)),ch=Math.min(H,Math.max(180,b.height+160));
 const cx=Math.max(0,Math.min(W-cw,b.x+b.width/2-cw/2)),cy=Math.max(0,Math.min(H-ch,b.y+b.height/2-ch/2));
 return `<div class="zoom" style="aspect-ratio:${cw}/${ch}"><img src="${esc(src)}" alt="문제 요소 주변 확대 화면" style="width:${pct(W,cw)};left:${pct(-cx,cw)};top:${pct(-cy,ch)}">${markerHtml(b,cx,cy,cw,ch)}</div><p class="evidence-note">빨간 상자가 문제 요소입니다.</p><details class="whole"><summary class="small">전체 화면에서 위치 보기</summary>${whole()}</details>`}
const safeColor=c=>/^#[0-9a-f]{3,8}$/i.test(c||'')?c:'';
function contrastData(i){
 const c=i.checks?.find(c=>c.id==='color-contrast'&&c.data?.contrastRatio);if(c)return c.data;
 const m=/contrast of ([\d.]+) \(foreground color: (#[0-9a-f]+), background color: (#[0-9a-f]+), font size: ([^,]+), font weight: (\w+)\)\. Expected contrast ratio of ([\d.]+:1)/i.exec(i.explanation||'');
 return m&&{contrastRatio:m[1],fgColor:m[2],bgColor:m[3],fontSize:m[4],fontWeight:m[5],expectedContrastRatio:m[6]}}
// 문제 상세의 ‘무엇이 문제인가요’ 체크 목록
function checkList(i){
 const mark=i.type==='violation'?'<span class="mark bad" aria-hidden="true">✕</span>':'<span class="mark warn" aria-hidden="true">?</span>';
 const d=i.ruleId==='color-contrast'&&contrastData(i);
 if(d){const fg=safeColor(d.fgColor),bg=safeColor(d.bgColor),sw=c=>c?`<span class="swatch" style="background:${c}"></span>`:'';
  const why=i.type==='review'&&(i.checks?.find(c=>c.id==='color-contrast')?.message||i.explanation);
  return `<ul class="checklist">${why?`<li>${mark}<div><strong>도구가 확정하지 못한 이유</strong><span>${esc(why)}</span></div></li>`:''}<li>${i.type==='review'?'<span class="mark" aria-hidden="true">•</span>':mark}<div><strong>현재 명도 대비 ${esc(String(d.contrastRatio).replace(/:1$/,''))}:1</strong><span>기준 ${esc(d.expectedContrastRatio||'4.5:1')} 이상이어야 합니다.</span></div></li><li><span class="mark" aria-hidden="true">•</span><div>글자색 ${sw(fg)}<code>${esc(d.fgColor)}</code> · 배경색 ${sw(bg)}<code>${esc(d.bgColor)}</code></div></li><li><span class="mark" aria-hidden="true">•</span><div>글자 크기 ${esc(d.fontSize)} · ${d.fontWeight==='bold'?'굵은 글자':'보통 굵기'}<span>큰 글자(24px 이상, 굵으면 약 18.7px 이상)는 3:1 기준입니다.</span></div></li></ul>`}
 const items=i.checks?.length?i.checks.map(c=>c.message).filter(Boolean):String(i.explanation||'').split('\n').map(s=>s.trim()).filter(s=>s&&!/:$/.test(s));
 if(!items.length)return `<p class="explanation">${esc(i.explanation)}</p>`;
 const anyOnly=i.checks?.length>1&&i.checks.every(c=>c.group==='any')||/Fix any of the following/.test(i.explanation||'')&&items.length>1;
 return `${i.type==='review'?'<p class="hint">도구가 확정하지 못한 항목입니다. 아래 이유를 보고 직접 확인하세요.</p>':anyOnly?'<p class="hint">아래 중 하나만 해결하면 됩니다.</p>':''}<ul class="checklist">${items.map(t=>`<li>${mark}<div>${esc(t)}</div></li>`).join('')}</ul>`}
const ruleStatus={violation:['문제 발견','red'],review:['확인 필요','amber'],pass:['통과','green'],inapplicable:['검사할 요소 없음',''],unknown:['결과 없음','']};
// 검사 범위 탭의 자동 규칙별 결과. 화면이 여러 개면 가장 나쁜 결과를 보여준다.
function ruleResults(r){
 const done=r.states.filter(s=>s.status==='completed'&&s.passedRuleIds);if(!S.rules||!done.length)return null;
 return Object.entries(S.rules).map(([id,rule])=>{const iss=r.issues.filter(i=>i.ruleId===id&&i.source==='axe-core'&&i.workflow!=='resolved');
  return {id,...rule,status:iss.some(i=>i.type==='violation')?'violation':iss.length?'review':done.some(s=>s.passedRuleIds.includes(id))?'pass':done.some(s=>s.inapplicableRuleIds?.includes(id))?'inapplicable':'unknown'}})}
function ruleResultsView(r){
 const rows=ruleResults(r);if(!rows)return '';
 const count=k=>rows.filter(x=>x.status===k).length,byId=Object.fromEntries(r.coverage.map(c=>[c.id,c]));
 const groups=[...new Set(rows.flatMap(x=>x.sc.length?x.sc:['기타']))].sort((a,b)=>a==='기타'?1:b==='기타'?-1:a.localeCompare(b,undefined,{numeric:true}));
 return `<section class="panel rule-panel"><h3>자동 검사 규칙 ${rows.length}개 결과</h3><p>검수 시작을 누르면 아래 자동 규칙을 모두 실행합니다. ${['violation','review','pass','inapplicable'].map(k=>`<span class="pill ${ruleStatus[k][1]}">${ruleStatus[k][0]} ${count(k)}</span>`).join(' ')}</p><p class="hint">자동 규칙은 55개 기준 중 ${groups.filter(g=>byId[g]).length}개 기준의 일부만 확인합니다. 나머지 기준과 자동으로 확인하지 못하는 부분은 ‘기준별 평가’에서 사람이 확인하세요. ‘검사할 요소 없음’은 해당 요소(예: 동영상, 표)가 페이지에 없었다는 뜻입니다.</p>
 ${rows.some(x=>['violation','review'].includes(x.status))?`<div class="rule-group"><h4>문제가 있거나 확인이 필요한 규칙</h4>${rows.filter(x=>['violation','review'].includes(x.status)).map(x=>`<div class="rule-row"><div>${esc(x.help)}<br><code class="small">${esc(x.id)}</code> · ${x.sc.map(esc).join(', ')||'기준 번호 없음'}</div><span class="pill ${ruleStatus[x.status][1]}">${ruleStatus[x.status][0]}</span></div>`).join('')}<p class="hint">자세한 위치와 내용은 ‘문제 목록’ 탭에서 확인하세요.</p></div>`:''}
 <details class="rule-all"><summary>기준별 전체 규칙 결과 보기 (${rows.length}개)</summary>${groups.map(g=>`<div class="rule-group"><h4>${g==='기타'?'특정 기준 번호가 없는 규칙':`${esc(g)} ${byId[g]?esc(byId[g].title):'(55개 A·AA 범위 밖 기준)'}`}</h4>${rows.filter(x=>g==='기타'?!x.sc.length:x.sc.includes(g)).map(x=>`<div class="rule-row"><div>${esc(x.help)}<br><code class="small">${esc(x.id)}</code></div><span class="pill ${ruleStatus[x.status][1]}">${ruleStatus[x.status][0]}</span></div>`).join('')}</div>`).join('')}</details></section>`}
async function loadEvidence(){const box=$('#evidence-box');if(!box)return;const r=selected(),i=r?.issues.find(i=>i.id===S.issue);if(!i?.screenshot)return;try{
 let src;if(S.sample)src=i.checkKind?`sample-${i.checkKind}.png`:'sample-evidence.png';else if(r.imported){$('#evidence-image').textContent='가져온 결과의 화면 파일은 원래 검사 PC에서 확인하세요.';return}else{const response=await fetch(S.api+'/api/evidence/'+i.screenshot,{headers:{Authorization:`Bearer ${S.token}`}});if(!response.ok)throw Error();if(lastBlob)URL.revokeObjectURL(lastBlob);src=lastBlob=URL.createObjectURL(await response.blob())}
 const img=new Image();img.src=src;await img.decode().catch(()=>{});
 if($('#evidence-box')!==box)return;$('#evidence-image').style.padding='0';$('#evidence-image').innerHTML=evidenceHtml(i,src,img.naturalWidth||(i.viewport==='mobile'?390:1440),img.naturalHeight||(i.viewport==='mobile'?844:1000));
 }catch{if($('#evidence-image'))$('#evidence-image').textContent='화면 파일을 불러올 수 없습니다. 엔진 연결을 확인하세요.'}}
function savedReviewer(){try{return localStorage.getItem('pagecheck-reviewer')||''}catch{return ''}}
function saveReviewer(name){try{localStorage.setItem('pagecheck-reviewer',name)}catch{}}
function howList(c){return c.how?.length?`<details class="how"><summary>이렇게 확인하세요</summary><ol>${c.how.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details>`:''}
// 해당 없음 제안은 검토자가 확인 버튼을 눌러야 기록된다.
function naPanel(r){const list=r.coverage.filter(c=>c.suggest);if(!list.length)return '';const locked=S.sample||r.imported;
 return `<form id="na-form" class="panel na-panel"><h3>해당 없음 제안 ${list.length}개</h3><p>${[...new Set(list.map(c=>c.suggest.reason))].map(esc).join('<br>')} 아래 기준은 이런 요소가 있어야 적용되므로 ‘비적용 확인’으로 한 번에 기록할 수 있습니다. 화면을 훑어보고 정말 없는지 확인한 뒤 누르세요.</p><p class="small muted">${list.map(c=>`${c.id} ${esc(c.title)}`).join(' · ')}</p><div class="na-actions"><label class="label" for="na-person">검토자</label><input id="na-person" class="field" name="reviewer" value="${esc(savedReviewer())}" required maxlength="100"><button class="btn primary" type="submit" ${locked?'disabled':''}>${list.length}개 비적용 확인</button></div><p class="error" id="na-error" role="alert"></p></form>`}
function coverageView(r){const left=r.coverage.filter(c=>c.outcome==='not-tested'),n=k=>left.filter(k).length;
 return `<div class="criteria-note"><strong>검수 시작은 자동 검사만 실행합니다.</strong> 자동 검사에서 문제가 없어도 기준 전체를 확인한 것은 아니어서 ‘사람 확인 전’으로 남습니다. 기준마다 <strong>이렇게 확인하세요</strong>를 열어 순서대로 확인하고, 판정을 기록하세요.${left.length?`<br>남은 기준 ${left.length}개 — 해당 없음 제안 ${n(c=>c.suggest)} · 자동 검사 후 나머지 확인 ${n(c=>!c.suggest&&c.auto==='clear')} · 처음부터 직접 확인 ${n(c=>!c.suggest&&c.auto!=='clear')}`:''}</div>${naPanel(r)}<div class="coverage-grid">${r.coverage.map(c=>`<div class="coverage-row"><span class="small muted">${c.id}<br>${esc(c.level)}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.review?.note||c.focus)}</p>${c.suggest?'<span class="pill auto blue">해당 없음 제안</span>':c.outcome==='not-tested'&&autoNames[c.auto]?`<span class="pill auto ${autoNames[c.auto][1]}">${autoNames[c.auto][0]}</span>`:''}${c.review?'':evidenceLines(c)+howList(c)}</div><button class="btn compact" data-action="review" data-sc="${c.id}"><span class="pill ${c.outcome==='fail'?'red':c.outcome==='pass'||c.outcome==='inapplicable'?'green':c.outcome==='needs-review'?'amber':''}">${outcomeNames[c.outcome]}</span>${icon('arrow')}</button></div>`).join('')}</div>`}
function checksView(r){const list=r.checks||[];if(!list.length)return '';const count=k=>r.issues.filter(i=>i.source==='pagecheck'&&i.stateId===k.id&&i.workflow!=='resolved').length;
 return `<section class="panel rule-panel"><h3>키보드·확대 자동 확인</h3><p>실제로 Tab 키를 누르고 화면 너비·글자 간격을 바꿔 보며 확인했습니다. 찾은 후보는 ‘문제 목록’의 확인 필요에 있고, 기준별 평가에도 결과가 붙습니다.</p>${list.map(k=>`<div class="rule-row"><div><strong>${esc(k.label)}</strong>${new Set(list.map(x=>x.url)).size>1?`<br><span class="small muted" style="word-break:break-all">${esc(k.url)}</span>`:''}${k.status==='completed'?Object.entries(k.notes).map(([sc,t])=>`<br><span class="small">${esc(sc)} · ${esc(t)}</span>`).join(''):`<br><span class="error small">${esc(k.error||'확인하지 못함')}</span>`}${k.screenshot?`<details class="rule-all"><summary>증거 화면 보기</summary>${shotBox(k)}</details>`:''}</div><span class="pill ${k.status!=='completed'?'amber':count(k)?'amber':'green'}">${k.status!=='completed'?'미확인':count(k)?`확인 필요 ${count(k)}`:'후보 없음'}</span></div>`).join('')}</section>`}
function scopeView(r){return `${ruleResultsView(r)}${checksView(r)}<div class="guide-grid"><section class="panel"><h3>등록한 검사 범위</h3><p><strong>${modeNames[r.request.mode]}</strong> · ${envNames[r.request.environment]} · ${r.request.implementation==='partial'?'일부 미구현':'구현 완료'}</p><p>${esc(r.request.changeNote||'변경 내용 미입력')}</p><ul>${r.request.urls.map(x=>`<li style="word-break:break-all">${esc(x)}</li>`).join('')}</ul><p class="small">${esc(r.engine.name)} ${esc(r.engine.version)} · ${esc(r.engine.browser)}<br>주소를 자동 확장하지 않으며 등록한 페이지·단계만 검사합니다.</p><h3 style="margin-top:24px">화면·상태별 결과</h3>${r.states.map(s=>`<div class="state-card"><span class="pill ${s.status==='completed'?'green':'amber'}">${s.status==='completed'?'검사 완료':'미검사'}</span> <strong class="small">${esc(s.label)} · ${s.viewport==='mobile'?'모바일':'PC'}</strong><p class="muted">${esc(s.title||s.url)}</p>${s.error?`<p class="error">${esc(s.error)}</p>`:''}</div>`).join('')}</section><section class="panel"><h3>실행 기록</h3>${r.error?`<p class="error" style="margin-bottom:15px">${esc(r.error)}</p>`:''}<ul class="log-list">${r.logs.map(l=>`<li><time>${fmt(l.at)}</time>${esc(l.message)}</li>`).join('')}</ul></section></div>`}
function guideView(){return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">GETTING STARTED</div><h1>주소를 등록하고, 수정 후 다시 확인하세요.</h1><p class="muted">데모·개발·운영 페이지를 위한 접근성 검수 도구입니다.</p></div></div><div class="guide-grid"><section class="panel"><h3>01 · PC에서 검사 엔진 실행</h3><p>로컬 엔진이 실제 Chrome 또는 Edge로 페이지를 검사합니다. 회사 페이지와 결과 화면은 이 PC에 저장됩니다.</p><ol><li>아래 버튼으로 실행 패키지를 내려받아 압축을 풉니다.</li><li><strong>PageCheck열기.bat</strong>를 더블클릭합니다. 처음 한 번은 자동 설치에 1~2분 걸립니다.</li><li>브라우저에 열린 PageCheck 화면에서 바로 검수합니다. 연결 키는 필요 없습니다. 검은 실행 창은 쓰는 동안 열어 두세요.</li></ol><a class="btn compact" href="pagecheck-local.zip" download>${icon('download')}로컬 실행 패키지</a><p class="hint">Windows·Chrome 또는 Edge·Node.js 20 이상이 필요합니다. Node.js가 없으면 실행할 때 설치 페이지가 열립니다. 이 온라인 화면에 엔진을 연결하는 방법은 패키지의 README-ko.md를 참고하세요.</p></section><section class="panel"><h3>02 · 모드에 맞게 검수</h3><p><strong>빠른 점검</strong> — 개발 중인 페이지 1개를 PC 화면으로 검사합니다.</p><p><strong>배포 전 검수</strong> — 최대 8개 주소의 PC·모바일 화면과 등록한 동작을 검사합니다.</p><p><strong>운영 점검</strong> — 최대 5개 주소를 이전 결과와 비교합니다. 정기 자동 실행은 포함하지 않습니다.</p><p class="hint">키보드·스크린리더 실제 이용, 문맥·대체텍스트·자막의 적절성은 사람 확인이 필요합니다.</p></section><section class="panel"><h3>03 · 로그인 뒤의 화면 검사</h3><p>새 검수에서 주소를 입력한 뒤 ‘로그인 브라우저 열기’를 누르세요. 열린 브라우저에서 직접 로그인하고 검수를 시작하면 해당 세션을 사용합니다.</p><p>비밀번호는 이 도구에 입력하지 않습니다. 브라우저 세션 파일과 증거 화면은 로컬 data 폴더에 남으므로 조직의 보관 정책에 따라 관리하세요.</p></section><section class="panel"><h3>04 · 결과 공유·재검수</h3><p>문제별 담당자와 상태를 저장하고 같은 조건으로 재검수하세요. 비교한 화면의 검사가 실패하면 해결이 아닌 ‘비교 불가’로 남습니다.</p><p>JSON 결과를 내보내고 다른 화면에서 가져올 수 있습니다. 가져온 결과는 열람용이며 수정·재검수는 원래 엔진에서 실행하세요.</p><p class="hint">팀 계정·이슈 관리 연동·자동 배포 차단은 이 버전에 포함되지 않습니다.</p></section></div>`}
function criteriaView(){return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">REVIEW POLICY</div><h1>기준은 엄격하게, 결과는 구분해서.</h1><p class="muted">현재 검사 엔진의 공통 기준은 WCAG 2.2의 A·AA 55개 성공 기준입니다.</p></div></div><div class="guide-grid"><section class="panel"><h3>자동 검사</h3><p>axe-core로 DOM·접근 가능한 이름·ARIA·계산 가능한 대비 등의 규칙을 검사합니다. 규칙의 위반과 사람이 확인해야 할 결과를 분리합니다.</p><p>검사 엔진 버전, 페이지 주소, 화면 크기와 단계를 각 검수 기록에 보존합니다.</p></section><section class="panel"><h3>기준 전체 평가</h3><p>자동 검사에서 문제가 없더라도 성공 기준 전체를 통과로 처리하지 않습니다. 55개 기준의 검토자·판정·근거를 별도로 기록합니다.</p><p>기준 전체 평가를 완료하지 않으면 배포 판단은 대기 상태로 남습니다.</p></section><section class="panel"><h3>국가별 기준 자료</h3><p>이전에 수집한 국가별 프로필은 참고 지식베이스입니다. 이 실행 버전은 국가별 법률 적용을 자동 확정하지 않으며 KWCAG·EN 전체의 검사 엔진을 구현한 버전도 아닙니다.</p><p>공공기관·학교 사업의 별도 계약 기준은 추가 검토 항목으로 관리하세요.</p></section><section class="panel"><h3>미검사와 미구현</h3><p>접속 실패·로그인 화면 이동·단계 실행 실패는 검사하지 못한 범위로 기록합니다. 일부 미구현으로 등록해도 문제를 자동 면제하지 않습니다.</p><p>녹화 영상·PDF 내부·실제 보조기술 사용은 별도의 검사 절차가 필요합니다.</p></section></div>`}
function dialogView(){if(!S.dialog)return '';let title='',body='',foot='',form='';
 if(S.dialog==='new'){
 title='새 페이지 검수';form='scan-form';body=`<div class="connection-card"><strong class="small">${S.online?'검사 엔진이 연결됐습니다':'실제 검수를 위해 로컬 엔진을 연결하세요'}</strong><p>${S.online?'검수 시작을 누르면 실제 연결을 다시 확인합니다.':'GitHub 화면 게시와 검사 엔진 실행은 별도입니다. 아래 안내에 따라 연결한 뒤 검수 시작을 누르세요.'}</p><details ${S.online?'':'open'}><summary>검사 엔진 실행·연결 설정</summary>${connectionSteps()}${connectionFields()}</details></div><div class="two-col"><div><label class="label" for="scan-name">검수 이름</label><input id="scan-name" class="field" name="name" placeholder="예: 회원가입 페이지 개선" required maxlength="100"></div><div><label class="label" for="scan-env">페이지 환경</label><select id="scan-env" class="field" name="environment"><option value="development">개발</option><option value="demo">데모</option><option value="production">운영</option></select></div></div><label class="label" for="scan-urls">검수할 페이지 주소 <span class="muted small">한 줄에 하나씩</span></label><textarea id="scan-urls" class="field" name="urls" placeholder="https://your-staging.example.com/signup" required></textarea><label class="label">검수 모드</label><div class="mode-grid">${[['quick','빠른 점검','페이지 1개 · PC 화면'],['release','배포 전 검수','최대 8개 주소 · PC·모바일'],['monitor','운영 점검','최대 5개 주소 · 이전 결과 비교']].map(([v,n,t])=>`<label class="mode-option"><input type="radio" name="mode" value="${v}" ${v==='quick'?'checked':''}><strong>${n}</strong><p>${t}</p></label>`).join('')}</div><label class="label" for="scan-change">변경한 내용 <span class="muted small">선택</span></label><textarea id="scan-change" class="field" name="changeNote" placeholder="예: 입력 필드와 오류 메시지 수정"></textarea><details><summary>로그인·테스트 단계 등 추가 설정</summary><label class="label"><input type="checkbox" name="partial"> 일부 기능 미구현</label><p class="hint">미구현 사항을 범위 정보에 남깁니다. 검사 결과를 자동 면제하지 않습니다.</p><div style="display:flex;align-items:center;gap:12px;margin-top:17px"><button type="button" class="btn compact" data-action="login">${icon('external')}로그인 브라우저 열기</button><span id="login-status" class="small muted">${S.sessionId?'브라우저 세션 연결됨':'로그인이 필요한 경우 사용'}</span></div><p class="hint">입력한 첫 주소를 브라우저로 엽니다. 해당 창에서 직접 로그인한 뒤 검수를 시작하세요.</p><label class="label" for="scan-steps">첫 페이지의 테스트 단계 <span class="muted small">JSON · 최대 10개</span></label><textarea id="scan-steps" class="field" name="steps" placeholder='[{"action":"click","selector":"button.menu","label":"메뉴 펼침"}]'></textarea><p class="hint">click / fill / press를 지원합니다. 단계마다 화면을 검사합니다. fill 값은 재시작 뒤 재사용하지 않으며 비밀번호를 입력하지 마세요.</p></details><p class="error" id="form-error" role="alert"></p>`;foot=`<span class="small muted">기준: WCAG 2.2 A·AA</span><div><button type="button" class="btn ghost" data-action="close">취소</button><button type="submit" class="btn primary">${icon('search')}검수 시작</button></div>`;
 }else if(S.dialog==='connect'){
 title='검사 엔진 연결';form='connect-form';body=`<div class="connection-card"><strong>PC에서 실제 브라우저로 검사합니다</strong>${connectionSteps()}</div>${connectionFields()}<p class="error" id="form-error" role="alert"></p>`;foot=`<a href="pagecheck-local.zip" class="btn compact" download>실행 패키지</a><button class="btn primary" type="submit">연결 확인</button>`;
 }else if(S.dialog.startsWith('export:')){
 const r=runById(S.dialog.slice(7));title='결과 내보내기';
 body=`<p><strong>${esc(r.request.name)}</strong> <span class="small muted">${fmt(r.createdAt)}</span></p><div class="export-options"><section class="export-option"><h3>HTML 보고서 <span class="pill green">공유용</span></h3><p>문제마다 위치를 빨간 상자로 표시한 화면, 요소 위치와 HTML, 수정 방법, 기준별 평가, 키보드·확대 확인 결과가 파일 하나에 들어 있습니다. 받는 사람은 PageCheck 없이 브라우저로 열면 됩니다.</p>${r.imported?'<p class="hint">가져온 결과라 화면은 들어가지 않습니다.</p>':''}<button type="button" class="btn primary" data-action="export-html" data-id="${r.id}">${icon('download')}HTML 보고서 받기</button></section><section class="export-option"><h3>JSON <span class="pill">다시 가져오기용</span></h3><p>다른 PageCheck에서 ‘결과 가져오기’로 열거나 보관할 때 씁니다. 화면 이미지는 들어 있지 않습니다.</p><button type="button" class="btn" data-action="export-json" data-id="${r.id}">${icon('download')}JSON 받기</button></section></div><p class="hint">두 파일 모두 검사한 페이지 정보가 들어 있으니 회사 안에서만 공유하고, 공개 저장소나 외부 게시판에 올리지 마세요.</p>`;
 foot=`<button type="button" class="btn" data-action="close">닫기</button>`;
 }else if(S.dialog.startsWith('delete:')){
 const r=S.runs.find(x=>x.id===S.dialog.slice(7));title='검수 기록 삭제';form='delete-form';
 body=r?`<input type="hidden" name="runId" value="${r.id}"><p><strong>${esc(r.request.name)}</strong></p><p class="small muted" style="word-break:break-all">${esc(r.request.urls[0])}${r.request.urls.length>1?` 외 ${r.request.urls.length-1}개`:''} · ${fmt(r.createdAt)}</p><div class="criteria-note danger-note">${r.imported?'이 화면에 가져온 결과만 지웁니다. 원래 검사한 PC의 기록은 그대로입니다.':'이 PC에서 문제 목록, 기준별 평가, 증거 화면이 모두 지워지며 되돌릴 수 없습니다.'+(r.status==='queued'?' 대기 중인 검사도 취소됩니다.':'')}</div><p class="hint">나중에 다시 보려면 지우기 전에 결과 내보내기로 JSON 파일을 받아 두세요.${r.imported?'':' 이 기록과 비교한 재검수 기록은 그대로 남습니다.'}</p><p class="error" id="form-error" role="alert"></p>`:'<p>이미 지워진 기록입니다.</p>';
 foot=`<button type="button" class="btn" data-action="close">취소</button>${r?`<button type="button" class="btn" data-action="export" data-id="${r.id}">${icon('download')}결과 내보내기</button><button class="btn primary danger" type="submit">${icon('trash')}삭제</button>`:''}`;
 }else if(S.dialog.startsWith('review:')){
 const c=selected().coverage.find(c=>c.id===S.dialog.slice(7));title=`${c.id} · ${c.title}`;form='review-form';body=`<input type="hidden" name="scId" value="${c.id}"><div class="criteria-note">${esc(c.focus)}</div>${c.suggest?'':c.auto==='clear'?'<p class="hint">자동 검사에서는 문제가 없었습니다. 자동 규칙이 확인하지 못하는 부분을 직접 확인하세요.</p>':c.auto==='not-covered'?'<p class="hint">이 기준에는 자동 검사 규칙이 없습니다. 화면을 직접 확인해 판정하세요.</p>':''}${c.suggest?`<p class="hint">해당 없음 제안: ${esc(c.suggest.reason)}</p>`:''}${c.evidence?.length?`<div class="evidence-box"><h3 class="label">키보드·확대 자동 확인 결과</h3>${evidenceLines(c)}${[...new Map(c.evidence.map(e=>[e.screenshot,e])).values()].map(e=>shotBox(e)).join('')}<p class="hint">자동 확인은 후보를 찾을 뿐입니다. 문제가 없다고 나와도 아래 순서대로 직접 확인하세요.</p></div>`:''}${c.how?.length?`<fieldset class="how-check"><legend class="label">이렇게 확인하세요</legend><p class="hint">확인한 항목을 체크하면 판정 근거에 들어갑니다.</p>${c.how.map((h,i)=>`<label><input type="checkbox" name="how" value="${i}"> ${esc(h)}</label>`).join('')}</fieldset>`:''}<a href="${esc(safeLink(c.url))}" target="_blank" rel="noreferrer">공식 성공 기준 확인 ↗</a><label class="label" for="review-outcome">해당 검수 범위의 판정</label><select id="review-outcome" class="field" name="outcome">${Object.entries(outcomeNames).filter(([v])=>v!=='not-tested').map(([v,n])=>`<option value="${v}" ${v===(c.review?.outcome||(c.suggest?'inapplicable':'needs-review'))?'selected':''}>${n}</option>`).join('')}</select><label class="label" for="review-person">검토자</label><input id="review-person" class="field" name="reviewer" value="${esc(c.review?.reviewer||savedReviewer())}" required><label class="label" for="review-note">판정 근거·확인한 화면과 상태 <span class="muted small">체크한 항목 외에 덧붙일 내용</span></label><textarea id="review-note" class="field" name="note" placeholder="예: 회원가입 1단계 PC 화면에서 확인. 예외로 본 근거가 있으면 적으세요.">${esc(c.review?.note||'')}</textarea><p class="error" id="form-error" role="alert"></p>`;foot=`<span class="small muted">미해결 자동 위반은 통과 처리할 수 없습니다.</span><button class="btn primary" type="submit" ${S.sample||selected().imported?'disabled':''}>평가 저장</button>`;
 }
 return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><form id="${form}"><header class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="닫기">${icon('close')}</button></header><div class="modal-body">${body}</div><footer class="modal-foot">${foot}</footer></form></section></div>`;
}
function openDialog(d){S.returnFocus=document.activeElement;S.dialog=d;render()}
async function confirmNa(f){const reviewer=f.reviewer.value.trim(),submit=f.querySelector('[type=submit]'),run=selected();if(!reviewer){$('#na-error').textContent='검토자를 입력하세요.';return}
 saveReviewer(reviewer);submit.disabled=true;let r=run,done=0;
 try{for(const c of run.coverage.filter(c=>c.suggest)){r=await api(`/api/runs/${run.id}/review`,{method:'POST',body:JSON.stringify({scId:c.id,outcome:'inapplicable',reviewer,note:`${c.suggest.reason} 검토자가 화면을 보고 해당 없음 제안을 확인함.`})});done++}
  toast(`${done}개 기준을 비적용 확인으로 기록했습니다.`)}
 catch(err){toast(`${done}개 기록 후 멈췄습니다: ${err.message}`)}
 S.runs=S.runs.map(x=>x.id===r.id?r:x);render()}
function closeDialog(){const previous=S.returnFocus?.dataset||{};S.dialog=null;render();[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===previous.action&&b.dataset.sc===previous.sc&&b.dataset.id===previous.id)?.focus()}
async function refresh(silent=false){
 try{if(!S.token&&location.origin===S.api){const x=await api('/api/local-session');S.token=x.token;sessionStorage.setItem('pagecheck-token',S.token)}
  const health=await api('/api/health');if(!health.ok)throw Error('검사 엔진 상태를 확인하지 못했습니다.');S.engineOutdated=(health.build||0)<ENGINE_BUILD;if(!S.token)throw Error('실행 창에 표시된 연결 키를 입력하세요.');
  const live=await api('/api/runs');S.runs=[...live,...S.runs.filter(r=>r.imported)];S.online=true;S.connectionError='';
 }catch(error){S.online=false;S.connectionError=error.message}finally{S.loading=false;if(!silent)render()}
}
async function action(name,el){
 if(name==='nav'){S.view=el.dataset.view;S.selected=null;S.sample=false;render()}
 if(name==='new')openDialog('new');if(name==='connect')openDialog('connect');if(name==='close')closeDialog();
 if(name==='env'){S.env=el.dataset.env;render()}
 if(name==='refresh'){await refresh();toast(S.online?'검수 기록을 갱신했습니다.':'엔진에 연결할 수 없습니다. 연결 설정을 확인하세요.')}
 if(name==='open'){S.selected=el.dataset.id;S.sample=false;S.tab='issues';S.issue=null;S.issueFilter='violation';render();window.scrollTo({top:0});$('#main').focus()}
 if(name==='back'){S.selected=null;S.sample=false;S.issue=null;render()}
 if(name==='tab'){S.tab=el.dataset.tab;render()}
 if(name==='issue'){S.issue=el.dataset.id;render()}
 if(name==='issue-filter'){S.issueFilter=el.dataset.filter;S.issue=null;render()}
 if(name==='review')openDialog('review:'+el.dataset.sc);
 if(name==='delete')openDialog('delete:'+el.dataset.id);
 if(name==='sample'){S.demo=await fetch('sample-run.json').then(r=>r.json());S.sample=true;S.selected=S.demo.id;S.tab='issues';S.issue=null;S.issueFilter='violation';render();window.scrollTo({top:0});$('#main').focus()}
 if(name==='export')openDialog('export:'+(el.dataset.id||selected().id));
 if(name==='export-json'){const r=runById(el.dataset.id);download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),`pagecheck-${r.id}.json`);toast('JSON 파일을 저장했습니다.')}
 if(name==='export-html')await exportReport(el.dataset.id,el);
 if(name==='recheck'){const r=selected();el.disabled=true;try{const next=await api(`/api/runs/${r.id}/recheck`,{method:'POST',body:'{}'});S.runs.unshift(next);S.selected=next.id;S.issue=null;S.tab='scope';render();toast('같은 조건으로 재검수를 시작했습니다.')}catch(e){toast(e.message);el.disabled=false}}
 if(name==='login'){
  if(!S.online)return toast('먼저 검사 엔진을 연결하세요.');const url=$('#scan-urls').value.trim().split('\n')[0];if(!url)return toast('검수할 첫 페이지 주소를 입력하세요.');el.disabled=true;
  try{const session=await api('/api/login',{method:'POST',body:JSON.stringify({url})});S.sessionId=session.id;$('#login-status').textContent='열린 창에서 로그인 후 검수를 시작하세요.';toast('로그인용 브라우저를 열었습니다.')}catch(e){toast(e.message)}finally{el.disabled=false}
 }
 if(name==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const r=JSON.parse(await input.files[0].text());if(!/^(?:import-)?[a-f0-9-]+$/.test(r.id)||!r.request?.urls||!Array.isArray(r.issues)||!Array.isArray(r.coverage)||!r.summary||r.issues.some(i=>!Array.isArray(i.scIds)||i.scIds.some(c=>!/^\d\.\d\.\d+$/.test(c))||!/^[a-f0-9]+$/.test(i.id))||r.coverage.some(c=>!/^\d\.\d\.\d+$/.test(c.id)))throw Error('PageCheck에서 내보낸 결과 파일을 선택하세요.');r.imported=true;r.id='import-'+r.id;if(S.runs.some(x=>x.id===r.id))throw Error('이미 가져온 결과입니다.');S.runs.unshift(r);saveImported();S.selected=r.id;S.sample=false;S.issue=null;render();toast('검수 결과를 가져왔습니다.')}catch(e){toast(e.message)}};input.click()}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;action(el.dataset.action,el).catch(err=>toast(err.message))});
document.addEventListener('input',e=>{if(e.target.id==='run-search'){S.query=e.target.value;render();const input=$('#run-search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}});
document.addEventListener('keydown',e=>{
 if(!S.dialog&&document.activeElement.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const order=['issues','coverage','scope'];const idx=order.indexOf(S.tab);S.tab=e.key==='Home'?order[0]:e.key==='End'?order[2]:order[(idx+(e.key==='ArrowRight'?1:2))%3];render();$('#tab-'+S.tab).focus();return}

 if(!S.dialog)return;if(e.key==='Escape'){closeDialog();return}if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select,.modal textarea,.modal a,.modal summary')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(f.id==='na-form'){e.preventDefault();confirmNa(f);return}if(!['scan-form','connect-form','issue-form','review-form','delete-form'].includes(f.id))return;e.preventDefault();const b=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type=submit]');submit.disabled=true;try{
  if(f.id==='connect-form'){setConnection(b.endpoint,b.token);await refresh(true);if(!S.online)throw Error(S.connectionError);S.dialog=null;render();toast('검사 엔진을 연결했습니다.')}
  if(f.id==='scan-form'){
   $('#form-error').textContent='';submit.textContent='연결 확인 중…';setConnection(b.endpoint,b.token);await refresh(true);if(!S.online)throw Error(S.connectionError);submit.textContent='검수 요청 중…';
   const urls=b.urls.split('\n').map(x=>x.trim()).filter(Boolean),steps=b.steps?.trim()?JSON.parse(b.steps):[];
   const request={name:b.name,urls,environment:b.environment,mode:b.mode,changeNote:b.changeNote,implementation:b.partial?'partial':'complete',steps,sessionId:S.sessionId};
   if(b.mode==='monitor'){const previous=S.runs.find(r=>r.status==='completed'&&r.request.urls[0]===urls[0]);request.baselineId=previous?.id||null}
   const r=await api('/api/runs',{method:'POST',body:JSON.stringify(request)});S.runs.unshift(r);S.selected=r.id;S.sample=false;S.issue=null;S.tab='scope';S.dialog=null;render();toast('검수를 시작했습니다.')}
  if(f.id==='issue-form'){const r=await api(`/api/runs/${selected().id}/issues/${b.issueId}`,{method:'PATCH',body:JSON.stringify(b)});S.runs=S.runs.map(x=>x.id===r.id?r:x);render();toast('진행 상태를 저장했습니다.')}
  if(f.id==='delete-form'){const r=S.runs.find(x=>x.id===b.runId);
   if(!r.imported)await api(`/api/runs/${r.id}`,{method:'DELETE'});
   S.runs=S.runs.filter(x=>x.id!==r.id);if(r.imported)saveImported();if(S.selected===r.id){S.selected=null;S.issue=null}
   S.dialog=null;render();$('#main')?.focus();toast(`‘${r.request.name}’ 기록을 지웠습니다.`)}
  if(f.id==='review-form'){const c=selected().coverage.find(x=>x.id===b.scId),checked=[...f.querySelectorAll('[name=how]:checked')].map(x=>c.how[+x.value]);delete b.how;
   b.note=[checked.length?'확인함: '+checked.map((h,i)=>`${i+1}) ${h}`).join(' '):'',b.note.trim()].filter(Boolean).join('\n');
   if(!b.note)throw Error('확인한 항목을 체크하거나 판정 근거를 적으세요.');saveReviewer(b.reviewer.trim());const r=await api(`/api/runs/${selected().id}/review`,{method:'POST',body:JSON.stringify(b)});S.runs=S.runs.map(x=>x.id===r.id?r:x);S.dialog=null;render();toast('기준 평가를 저장했습니다.')}
 }catch(err){const error=$('#form-error');if(error)error.textContent=err.message;else toast(err.message)}finally{if(submit.isConnected){submit.disabled=false;if(f.id==='scan-form')submit.textContent='검수 시작'}}
});
try{S.runs=JSON.parse(localStorage.getItem('pagecheck-imports')||'[]')}catch{}
render();
fetch('axe-rules.json').then(r=>r.json()).then(m=>{S.rules=m.rules;if(!S.dialog)render()}).catch(()=>{});
if(['127.0.0.1','localhost'].includes(location.hostname)){S.api=location.origin;refresh()}else if(S.token){refresh()}else{S.loading=false;render()}
setInterval(async()=>{if(!S.online||!S.runs.some(r=>['running','queued'].includes(r.status)))return;await refresh(true);if(!S.dialog&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))render()},2000);
